class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = sum(1 for x in nums if x == k)
        best = 0
        for v in range(1, 51):
            if v == k:
                continue
            l = cv = ck = 0
            for r, x in enumerate(nums):
                cv += x == v
                ck += x == k
                while l <= r and ck >= cv:
                    cv -= nums[l] == v
                    ck -= nums[l] == k
                    l += 1
                best = max(best, cv - ck)
        return base + best

