class Solution {
public:
    int maxFrequency(vector<int>& nums, int k) {
        int base = 0;
        for (int x : nums) base += x == k;
        int n = nums.size(), best = 0;
        for (int v = 1; v <= 50; v++) {
            if (v == k) continue;
            int l = 0, cv = 0, ck = 0;
            for (int r = 0; r < n; r++) {
                cv += nums[r] == v;
                ck += nums[r] == k;
                while (l <= r && ck >= cv) { cv -= nums[l] == v; ck -= nums[l] == k; l++; }
                best = max(best, cv - ck);
            }
        }
        return base + best;
    }
};

