class Solution {
    public int maxFrequency(int[] nums, int k) {
        int base = 0;
        for (int x : nums) if (x == k) base++;
        int n = nums.length, best = 0;
        for (int v = 1; v <= 50; v++) {
            if (v == k) continue;
            int l = 0, cv = 0, ck = 0;
            for (int r = 0; r < n; r++) {
                if (nums[r] == v) cv++;
                if (nums[r] == k) ck++;
                while (l <= r && ck >= cv) { if (nums[l] == v) cv--; if (nums[l] == k) ck--; l++; }
                best = Math.max(best, cv - ck);
            }
        }
        return base + best;
    }
}

