var maxFrequency = function(nums, k) {
    let base = 0;
    for (const x of nums) if (x === k) base++;
    let best = 0;
    for (let v = 1; v <= 50; v++) {
        if (v === k) continue;
        let l = 0, cv = 0, ck = 0;
        for (let r = 0; r < nums.length; r++) {
            if (nums[r] === v) cv++;
            if (nums[r] === k) ck++;
            while (l <= r && ck >= cv) { if (nums[l] === v) cv--; if (nums[l] === k) ck--; l++; }
            best = Math.max(best, cv - ck);
        }
    }
    return base + best;
};
